<script setup lang="ts">
import type {LibraryItem} from '~/types/community'
const props=defineProps<{workId:number}>(),auth=useAuth(),{loginOpen}=useForum()
const state=ref<'wish'|'reading'|'finished'>('wish'),note=ref(''),isPublic=ref(false),exists=ref(false),busy=ref(false),error=ref(''),message=ref('')
async function load(){exists.value=false;note.value='';state.value='wish';isPublic.value=false;if(!auth.user.value)return;const id=auth.user.value.id;try{const items=await auth.request<LibraryItem[]>('/library');if(auth.user.value?.id!==id)return;const item=items.find(item=>item.workId===props.workId);if(item){state.value=item.state;note.value=item.note;isPublic.value=item.isPublic;exists.value=true}}catch(e){error.value=(e as Error).message}}
async function save(remove=false){if(!auth.user.value){loginOpen.value=true;return}busy.value=true;error.value='';message.value='';try{await auth.request('/library/'+props.workId,remove?{}:{state:state.value,note:note.value,isPublic:isPublic.value},remove?'DELETE':'PUT');exists.value=!remove;if(remove){note.value='';isPublic.value=false}message.value=remove?'已从书单移除。':'书单已保存。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{await auth.initialize();await load()});watch(()=>[props.workId,auth.user.value?.id],load)
</script>
<template><section class="experience-card library-editor"><h2>留在我的书单里</h2><form v-if="auth.user.value" @submit.prevent="save()"><fieldset class="plain-fieldset" :disabled="busy"><label class="community-field">阅读状态<select v-model="state"><option value="wish">想读</option><option value="reading">在读</option><option value="finished">已读</option></select></label><label class="community-field">一句短评<textarea v-model="note" rows="3" maxlength="500" placeholder="请勿在公开短评中透露剧情。"></textarea></label><label class="inline-check"><input v-model="isPublic" type="checkbox" />将这一条书单与短评展示在我的公开主页</label><small class="muted">默认仅本人可见；公开后，访客可以阅读这条短评。</small><div class="field-pair"><button class="button primary" :disabled="busy">{{ busy?'保存中…':'保存到书单' }}</button><button v-if="exists" type="button" class="button secondary" @click="save(true)">移出书单</button></div></fieldset></form><button v-else class="button secondary" @click="loginOpen=true">登录后记录阅读状态</button><p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="message" class="form-success" role="status">{{ message }}</p></section></template>
